<span class="line">    ACCEPTED <span class="token operator">=</span> <span class="token string">"accepted"</span>  <span class="token comment"># ✅ تم القبول</span></span>
<span class="line">    REJECTED <span class="token operator">=</span> <span class="token string">"rejected"</span>  <span class="token comment"># ❌ تم الرفض</span></span>
<span class="line">    CANCEL <span class="token operator">=</span> <span class="token string">"cancel"</span>  <span class="token comment"># 🔄 تم الإلغاء</span></span>
<span class="line">    UNFRIEND <span class="token operator">=</span> <span class="token string">"unfriend"</span>  <span class="token comment"># 🔄 تم الإلغاء الصداقة</span></span>
<span class="line">    BLOCKED <span class="token operator">=</span> <span class="token string">"blocked"</span>  <span class="token comment"># 🚫 الحظر</span></span>
<span class="line">    MUTED <span class="token operator">=</span> <span class="token string">"muted"</span>  <span class="token comment"># 🔕 الكتم</span></span>
<span class="line">    FROZEN <span class="token operator">=</span> <span class="token string">"frozen"</span>  <span class="token comment"># 🧊 تجميد</span></span>
<span class="line">    ARCHIVED <span class="token operator">=</span> <span class="token string">"archived"</span>  <span class="token comment"># 📦 مؤرشف</span></span>
<span class="line">    FOLLOWING <span class="token operator">=</span> <span class="token string">"following"</span>  <span class="token comment"># 👥 متابعة</span></span>
<span class="line">    UNFOLLOWED <span class="token operator">=</span> <span class="token string">"unfollowed"</span>  <span class="token comment"># 🚫 إلغاء المتابعة</span></span>
<span class="line">    REPORTED <span class="token operator">=</span> <span class="token string">"reported"</span>  <span class="token comment"># 🚨 تم الإبلاغ عنه</span></span>
<span class="line">    SPAM <span class="token operator">=</span> <span class="token string">"spam"</span>  <span class="token comment"># 🗑️ بريد مزعج</span></span>
<span class="line">    DELETED <span class="token operator">=</span> <span class="token string">"deleted"</span>  <span class="token comment"># 🗑️ محذوف</span></span>
<span class="line">    FAVORITE <span class="token operator">=</span> <span class="token string">"favorite"</span>  <span class="token comment"># 🌟 مفضل</span></span>
<span class="line">    TEMPORARILY_BLOCKED <span class="token operator">=</span> <span class="token string">"temporarily_blocked"</span>  <span class="token comment"># ⏳ حظر مؤقت</span></span>
<span class="line">    VERIFIED <span class="token operator">=</span> <span class="token string">"verified"</span>  <span class="token comment"># ✔️ تم التحقق</span></span>
<span class="line">    REQUEST_RESENT <span class="token operator">=</span> <span class="token string">"request_resent"</span>  <span class="token comment"># 🔄 تم إعادة الإرسال</span></span>
<span class="line">    SUGGESTED <span class="token operator">=</span> <span class="token string">"suggested"</span>  <span class="token comment"># 💡 مقترح</span></span>
<span class="line">    IGNORED <span class="token operator">=</span> <span class="token string">"ignored"</span>  <span class="token comment"># 🛑 تم التجاهل</span></span>
<span class="line">    INACTIVE <span class="token operator">=</span> <span class="token string">"inactive"</span>  <span class="token comment"># ⚠️ غير نشط</span></span>
<span class="line">    LIMITED <span class="token operator">=</span> <span class="token string">"limited"</span>  <span class="token comment"># 🚫 محدود</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># 📜 قائمة الحالات الممكنة مع النصوص المقابلة</span></span>
<span class="line">    STATUS_CHOICES <span class="token operator">=</span> <span class="token punctuation">(</span></span>
<span class="line">        <span class="token punctuation">(</span>NOTSEND<span class="token punctuation">,</span> <span class="token string">"NotSent"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🚫 لم يتم الإرسال</span></span>
<span class="line">        <span class="token punctuation">(</span>SEND<span class="token punctuation">,</span> <span class="token string">"Send"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># ✉️ تم الإرسال</span></span>
<span class="line">        <span class="token punctuation">(</span>WAITING<span class="token punctuation">,</span> <span class="token string">"Waiting"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># ⏳ في انتظار الرد</span></span>
<span class="line">        <span class="token punctuation">(</span>ACCEPTED<span class="token punctuation">,</span> <span class="token string">"Accepted"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># ✅ تم القبول</span></span>
<span class="line">        <span class="token punctuation">(</span>REJECTED<span class="token punctuation">,</span> <span class="token string">"Rejected"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># ❌ تم الرفض</span></span>
<span class="line">        <span class="token punctuation">(</span>CANCEL<span class="token punctuation">,</span> <span class="token string">"Cancel"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🔄 تم الإلغاء</span></span>
<span class="line">        <span class="token punctuation">(</span>UNFRIEND<span class="token punctuation">,</span> <span class="token string">"Unfriend"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🔄 تم الإلغاء</span></span>
<span class="line">        <span class="token punctuation">(</span>BLOCKED<span class="token punctuation">,</span> <span class="token string">"Blocked"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🚫 الحظر</span></span>
<span class="line">        <span class="token punctuation">(</span>MUTED<span class="token punctuation">,</span> <span class="token string">"Muted"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🔕 الكتم</span></span>
<span class="line">        <span class="token punctuation">(</span>FROZEN<span class="token punctuation">,</span> <span class="token string">"Frozen"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🧊 تجميد</span></span>
<span class="line">        <span class="token punctuation">(</span>ARCHIVED<span class="token punctuation">,</span> <span class="token string">"Archived"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 📦 مؤرشف</span></span>
<span class="line">        <span class="token punctuation">(</span>FOLLOWING<span class="token punctuation">,</span> <span class="token string">"Following"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 👥 متابعة</span></span>
<span class="line">        <span class="token punctuation">(</span>UNFOLLOWED<span class="token punctuation">,</span> <span class="token string">"Unfollowed"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🚫 إلغاء المتابعة</span></span>
<span class="line">        <span class="token punctuation">(</span>REPORTED<span class="token punctuation">,</span> <span class="token string">"Reported"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🚨 تم الإبلاغ عنه</span></span>
<span class="line">        <span class="token punctuation">(</span>SPAM<span class="token punctuation">,</span> <span class="token string">"Spam"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🗑️ بريد مزعج</span></span>
<span class="line">        <span class="token punctuation">(</span>DELETED<span class="token punctuation">,</span> <span class="token string">"Deleted"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🗑️ محذوف</span></span>
<span class="line">        <span class="token punctuation">(</span>FAVORITE<span class="token punctuation">,</span> <span class="token string">"Favorite"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🌟 مفضل</span></span>
<span class="line">        <span class="token punctuation">(</span>TEMPORARILY_BLOCKED<span class="token punctuation">,</span> <span class="token string">"TemporarilyBlocked"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># ⏳ حظر مؤقت</span></span>
<span class="line">        <span class="token punctuation">(</span>VERIFIED<span class="token punctuation">,</span> <span class="token string">"Verified"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># ✔️ تم التحقق</span></span>
<span class="line">        <span class="token punctuation">(</span>REQUEST_RESENT<span class="token punctuation">,</span> <span class="token string">"RequestResent"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🔄 تم إعادة الإرسال</span></span>
<span class="line">        <span class="token punctuation">(</span>SUGGESTED<span class="token punctuation">,</span> <span class="token string">"Suggested"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 💡 مقترح</span></span>
<span class="line">        <span class="token punctuation">(</span>IGNORED<span class="token punctuation">,</span> <span class="token string">"Ignored"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🛑 تم التجاهل</span></span>
<span class="line">        <span class="token punctuation">(</span>INACTIVE<span class="token punctuation">,</span> <span class="token string">"Inactive"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># ⚠️ غير نشط</span></span>
<span class="line">        <span class="token punctuation">(</span>LIMITED<span class="token punctuation">,</span> <span class="token string">"Limited"</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 🚫 محدود</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># 🔑 Friend Request UUID Essential Field حقل أساسي UUID لطلب الصداقة</span></span>
<span class="line">    <span class="token builtin">id</span> <span class="token operator">=</span> models<span class="token punctuation">.</span>UUIDField<span class="token punctuation">(</span>primary_key<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">,</span> default<span class="token operator">=</span>uuid<span class="token punctuation">.</span>uuid4<span class="token punctuation">,</span> editable<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token comment"># 🧑 User receiving the request  المستخدم المستلم للطلب</span></span>
<span class="line">    created_for <span class="token operator">=</span> models<span class="token punctuation">.</span>ForeignKey<span class="token punctuation">(</span></span>
<span class="line">        User<span class="token punctuation">,</span> related_name<span class="token operator">=</span><span class="token string">"received_friendshiprequests"</span><span class="token punctuation">,</span> on_delete<span class="token operator">=</span>models<span class="token punctuation">.</span>CASCADE</span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line">    <span class="token comment"># 🧑 The user who sent the request  المستخدم المرسل للطلب</span></span>
<span class="line">    created_by <span class="token operator">=</span> models<span class="token punctuation">.</span>ForeignKey<span class="token punctuation">(</span></span>
<span class="line">        User<span class="token punctuation">,</span> related_name<span class="token operator">=</span><span class="token string">"created_friendshiprequests"</span><span class="token punctuation">,</span> on_delete<span class="token operator">=</span>models<span class="token punctuation">.</span>CASCADE</span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line">    <span class="token comment"># 📅 Creation date تاريخ الإنشاء</span></span>
<span class="line">    created_at <span class="token operator">=</span> models<span class="token punctuation">.</span>DateTimeField<span class="token punctuation">(</span>auto_now_add<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token comment"># 📝 Order Status  حالة الطلب</span></span>
<span class="line">    <span class="token comment"># 🚫 الحالة الافتراضية: "لم يتم الإرسال"</span></span>
<span class="line">    status <span class="token operator">=</span> models<span class="token punctuation">.</span>CharField<span class="token punctuation">(</span></span>
<span class="line">        max_length<span class="token operator">=</span><span class="token number">20</span><span class="token punctuation">,</span> choices<span class="token operator">=</span>STATUS_CHOICES<span class="token punctuation">,</span> default<span class="token operator">=</span>NOTSEND<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">class</span> <span class="token class-name">Meta</span><span class="token punctuation">:</span></span>
<span class="line">        ordering <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token string">"-created_at"</span><span class="token punctuation">,</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">def</span> <span class="token function">__str__</span><span class="token punctuation">(</span>self<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token string">"%s"</span> <span class="token operator">%</span> self<span class="token punctuation">.</span>status</span>
<span class="line"></span>
<span class="line">    <span class="token comment"># 🔍 Retrieve All Friend Requests by User and Status 🔍</span></span>
<span class="line">    <span class="token comment"># 🧑‍🤝‍🧑 جلب جميع طلبات الصداقة بناءً على المستخدم والحالة</span></span>
<span class="line">    <span class="token decorator annotation punctuation">@staticmethod</span></span>
<span class="line">    <span class="token keyword">def</span> <span class="token function">get_friends_by_status</span><span class="token punctuation">(</span>user<span class="token punctuation">,</span> status<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token triple-quoted-string string">"""جلب الأصدقاء بناءً على حالة محددة"""</span></span>
<span class="line">        <span class="token keyword">if</span> status <span class="token operator">==</span> FriendshipRequest<span class="token punctuation">.</span>ACCEPTED<span class="token punctuation">:</span></span>
<span class="line">            <span class="token keyword">return</span> User<span class="token punctuation">.</span>objects<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span></span>
<span class="line">                received_friendshiprequests__created_by<span class="token operator">=</span>user<span class="token punctuation">,</span></span>
<span class="line">                received_friendshiprequests__status<span class="token operator">=</span>status<span class="token punctuation">,</span></span>
<span class="line">            <span class="token punctuation">)</span> <span class="token operator">|</span> User<span class="token punctuation">.</span>objects<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span></span>
<span class="line">                created_friendshiprequests__created_for<span class="token operator">=</span>user<span class="token punctuation">,</span></span>
<span class="line">                created_friendshiprequests__status<span class="token operator">=</span>status<span class="token punctuation">,</span></span>
<span class="line">            <span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> User<span class="token punctuation">.</span>objects<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span></span>
<span class="line">            received_friendshiprequests__created_by<span class="token operator">=</span>user<span class="token punctuation">,</span></span>
<span class="line">            received_friendshiprequests__status<span class="token operator">=</span>status<span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span></span>
